#!/usr/bin/env python3
import sys
import time

filename = "dummy_test_file.txt"

# Create a dummy file to open
with open(filename, 'w') as f:
    f.write("testing fd limits\n")

files = []
print(f"Opening '{filename}' repeatedly...")

try:
    while True:
        f = open(filename, 'r')
        files.append(f)  # Keep reference to prevent garbage collection from closing it

        if len(files) % 50000 == 0:
            print(f"Successfully opened {len(files)} files...")

except OSError as e:
    print(f"\nHit file descriptor limit after opening {len(files)} files!")
    print(f"OS Error: {e}")
except KeyboardInterrupt:
    pass

print("\nHolding files open in memory. Press Ctrl+C to release and exit.")
try:
    while True:
        time.sleep(1)
except KeyboardInterrupt:
    print("\nExiting and closing files.")
